"""The SKOS export of the two vocabulary files (openddil ADR-0056 §10), generated by
`scripts/generate_vocabulary_skos.py` into `policy/registry/lifecycle_status.skos.ttl` and
`policy/classification/dimensions.skos.ttl`.

WHAT EACH GROUP DEFENDS
  drift       the shipped exports are what the generator renders from the shipped files, byte for byte
              and LF only; `--check` fails on a stale or missing export (seeded), and `--help` writes
              nothing.
  refusal     a vocabulary the validator refuses is not exported, and nothing is written.
  graph       the Turtle parses, every term is a `skos:Concept` IN its scheme under its own identity,
              a hierarchical dimension's order survives as a `skos:memberList`, a label with `"` and
              `\\` round-trips, and `required`/`empty_means` are not exported.

Fixture terms are neutral (`dim-s`, `dim-h`, `v1`, `level-a`), never a real dimension.

Run:  uv run pytest tests/security/test_vocabulary_skos.py -q
"""
from __future__ import annotations

import hashlib
import importlib.util
import shutil
import subprocess
import sys
from pathlib import Path

import pytest
import yaml

_REPO = Path(__file__).resolve().parents[2]
_GEN = _REPO / "scripts" / "generate_vocabulary_skos.py"
_POLICY = _REPO / "policy"
_OUT = ("registry/lifecycle_status.skos.ttl", "classification/dimensions.skos.ttl")


def _load():
    spec = importlib.util.spec_from_file_location("generate_vocabulary_skos", _GEN)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


gen = _load()


def _urn(label):
    """A valid, distinct term identity per label (UUID v7 shape), derived, never typed."""
    h = hashlib.sha256(label.encode()).hexdigest()
    return f"urn:uuid:{h[:8]}-{h[8:12]}-7{h[13:16]}-8{h[17:20]}-{h[20:32]}"


def _dim(name, typ, vocab, **over):
    row = {"name": name, "identity": _urn(name), "type": typ, "vocabulary": list(vocab),
           "identities": {v: _urn(f"{name}.{v}") for v in vocab}, "owner": "owner", "ratified_by": "owner"}
    row.update(over)
    return row


def _run(*args, cwd=_REPO):
    return subprocess.run([sys.executable, str(_GEN), *args], cwd=cwd, capture_output=True, text=True)


def _policy_copy(tmp_path, monkeypatch):
    pol = tmp_path / "policy"
    shutil.copytree(_POLICY, pol, ignore=shutil.ignore_patterns("__pycache__"))
    monkeypatch.setattr(gen, "_POLICY", pol)
    return pol


def _main(monkeypatch, *args):
    monkeypatch.setattr(sys, "argv", [str(_GEN), *args])
    return gen.main()


# ---- drift ----------------------------------------------------------------------------------------------

def test_the_shipped_exports_are_current():
    r = _run("--check")
    assert r.returncode == 0, r.stdout + r.stderr


def test_the_shipped_exports_are_what_build_renders_and_lf_only():
    rendered, errors = gen.build()
    assert errors == [] and sorted(rendered) == sorted(_OUT)     # control: both rendered
    for rel, text in rendered.items():
        on_disk = (_POLICY / rel).read_bytes()
        assert on_disk == text.encode("utf-8"), rel
        assert b"\r" not in on_disk, rel


def test_help_writes_nothing_and_names_check(tmp_path):
    r = _run("--help", cwd=tmp_path)
    assert r.returncode == 0 and "--check" in r.stdout
    assert list(tmp_path.iterdir()) == []


@pytest.mark.parametrize("rel", _OUT)
def test_check_fails_on_a_stale_export(tmp_path, monkeypatch, rel):
    pol = _policy_copy(tmp_path, monkeypatch)
    assert _main(monkeypatch, "--check") == 0                   # the control: the copy is current
    (pol / rel).write_bytes((pol / rel).read_bytes() + b"\n")
    assert _main(monkeypatch, "--check") == 1


@pytest.mark.parametrize("rel", _OUT)
def test_check_fails_on_a_missing_export_and_writes_nothing(tmp_path, monkeypatch, rel):
    pol = _policy_copy(tmp_path, monkeypatch)
    (pol / rel).unlink()
    assert _main(monkeypatch, "--check") == 1
    assert not (pol / rel).exists()


def test_check_fails_when_the_source_changes(tmp_path, monkeypatch):
    pol = _policy_copy(tmp_path, monkeypatch)
    src = pol / "registry" / "lifecycle_status.yaml"
    raw = yaml.safe_load(src.read_text(encoding="utf-8"))
    raw["statuses"].append("status-a")
    raw["identities"]["status-a"] = _urn("status-a")
    src.write_text(yaml.safe_dump(raw, sort_keys=False), encoding="utf-8")
    assert _main(monkeypatch, "--check") == 1
    assert _main(monkeypatch) == 0                               # regenerate
    assert _main(monkeypatch, "--check") == 0
    assert '"status-a"' in (pol / _OUT[0]).read_text(encoding="utf-8")


# ---- refusal -----------------------------------------------------------------------------------------------

def test_a_refused_vocabulary_is_not_exported(tmp_path, monkeypatch):
    pol = _policy_copy(tmp_path, monkeypatch)
    before = {rel: (pol / rel).read_bytes() for rel in _OUT}
    src = pol / "registry" / "lifecycle_status.yaml"
    raw = yaml.safe_load(src.read_text(encoding="utf-8"))
    raw["identities"]["active"] = "active"
    src.write_text(yaml.safe_dump(raw, sort_keys=False), encoding="utf-8")
    assert _main(monkeypatch) == 2
    assert {rel: (pol / rel).read_bytes() for rel in _OUT} == before


def test_a_collision_across_the_files_is_not_exported(tmp_path, monkeypatch):
    pol = _policy_copy(tmp_path, monkeypatch)
    ls = yaml.safe_load((pol / "registry" / "lifecycle_status.yaml").read_text(encoding="utf-8"))
    cd = pol / "classification" / "dimensions.yaml"
    cd.write_text(yaml.safe_dump({"generator": ls["generator"],
                                  "dimensions": [_dim("dim-s", "set", ["v1"])]}), encoding="utf-8")
    assert _main(monkeypatch, "--check") == 1                    # the control: valid, only stale
    cd.write_text(yaml.safe_dump({"generator": ls["generator"], "dimensions": [
        _dim("dim-s", "set", ["v1"], identity=ls["identity"])]}), encoding="utf-8")
    assert _main(monkeypatch, "--check") == 2


# ---- the graph ------------------------------------------------------------------------------------------------

_SKOS = "http://www.w3.org/2004/02/skos/core#"


def _graph(text):
    rdflib = pytest.importorskip("rdflib")
    return rdflib, rdflib.Graph().parse(data=text, format="turtle")


def test_the_lifecycle_export_has_one_concept_per_status_in_its_scheme():
    raw = yaml.safe_load((_POLICY / "registry" / "lifecycle_status.yaml").read_text(encoding="utf-8"))
    rdflib, g = _graph(gen.lifecycle_ttl(raw))
    S, U = rdflib.Namespace(_SKOS), rdflib.URIRef
    assert (U(raw["identity"]), rdflib.RDF.type, S.ConceptScheme) in g
    concepts = set(g.subjects(rdflib.RDF.type, S.Concept))
    assert concepts == {U(raw["identities"][s]) for s in raw["statuses"]}
    for s in raw["statuses"]:
        c = U(raw["identities"][s])
        assert (c, S.inScheme, U(raw["identity"])) in g
        assert (c, S.notation, rdflib.Literal(s)) in g


def test_a_dimension_export_keeps_order_escapes_labels_and_leaves_out_policy():
    odd = 'dim-"q\\'
    raw = {"generator": "g", "dimensions": [
        _dim("dim-s", "set", ["v1", "v2"], required=True),
        _dim("dim-h", "hierarchical", ["level-c", "level-a", "level-b"]),
        _dim(odd, "set", ['v"1'], empty_means="admits_no_one")]}
    text = gen.dimensions_ttl(raw)
    rdflib, g = _graph(text)
    S, U = rdflib.Namespace(_SKOS), rdflib.URIRef
    assert set(g.subjects(rdflib.RDF.type, S.ConceptScheme)) == {U(_urn(n)) for n in ("dim-s", "dim-h", odd)}
    assert (U(_urn(odd)), S.prefLabel, rdflib.Literal(odd)) in g
    assert (U(_urn(f'{odd}.v"1')), S.notation, rdflib.Literal('v"1')) in g
    coll = next(g.subjects(rdflib.RDF.type, S.OrderedCollection))
    from rdflib.collection import Collection
    members = list(Collection(g, next(g.objects(coll, S.memberList))))
    assert members == [U(_urn(f"dim-h.{v}")) for v in ("level-c", "level-a", "level-b")]
    assert len(list(g.subjects(rdflib.RDF.type, S.OrderedCollection))) == 1    # the set dims have none
    assert "required" not in text and "admits_no_one" not in text and "empty_means" not in text
